type IntentResult =
  | { kind: 'patch'; patch: FilterPatch }
  | { kind: 'choose'; choice: Choice }
  | { kind: 'out-of-scope' };

type FacetValues = Record<FacetKey, string[]>;

interface IntentContext {
  filters: SearchFilters;
  facets: FacetValues;
  choice: Choice | null;
}

interface IntentClient {
  interpret(transcript: string, context: IntentContext, signal: AbortSignal): Promise<unknown>;
}

interface SearchPage {
  products: ProductCard[];
  total: number;
}

interface CatalogGateway {
  facets(category: string | null, signal: AbortSignal): Promise<FacetValues>;
  search(filters: SearchFilters, signal: AbortSignal): Promise<SearchPage>;
}

type ValidateReply = (
  raw: unknown,
  transcript: string,
  context: IntentContext,
  catalog: CatalogGateway,
  signal: AbortSignal,
) => Promise<IntentResult | null>;

interface SpeechClient {
  unlock(): void;
  listen(onLive: () => void, onPartial: (text: string) => void, signal: AbortSignal): Promise<string | null>;
  finish(): void;
  speak(text: string, signal: AbortSignal): Promise<void>;
}
